import {validateCourses,filterCourses,courseCards} from './courses.js';
import {SITE_LANGUAGE,englishStory,containsVietnamese} from './language.js';
import {escapeHTML as e,uid,loadState,saveState,validateState,mergeState,STORAGE_KEY} from './core.js';
import {ZONE,calendarDate,validateExam,duplicateExam,examState,orderedExams,tickLabel,deadline} from './exams.js';
import {cachedEdition,fetchEdition,dailyCase,localCaseSections,REFRESH_MS,safeSource} from './reading.js';
import {NEWS_MEDIA} from './news-media.js';
import {MEDIA_SNAPSHOTS} from './media-snapshots.js';
import {inspectFile,putFile,getFile,loadPdf,officeSections,pdfSections} from './documents.js';

const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal'),loaded=loadState();
let state=loaded.state,storageError=loaded.error,DATA,catalog=[],route='home',query='',filter='all',edition=cachedEdition(),busy=false,readingError='',newsIndex=0,caseOffset=0,caseMode='web',localIndex=0,lastFocus,modalToken=0,activePdf=null,todaySignature='',ONLINE={version:1,checkedOn:'2026-11-17',courses:[]},coursesError='',onlineQuery='',providerFilter='all',deliveryFilter='all';
document.documentElement.lang=SITE_LANGUAGE;
const paths={home:'m3 10 9-7 9 7v11h-7v-7h-4v7H3Z',book:'M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v16h-6a4 4 0 0 0-3 1 4 4 0 0 0-3-1H3Zm9 2v15',menu:'M4 6h16M4 12h16M4 18h16',arrow:'M4 12h16m-6-6 6 6-6 6',plus:'M12 4v16M4 12h16',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M17 7l1-1',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',calendar:'M3 5h18v16H3ZM7 2v6m10-6v6M3 10h18',close:'m6 6 12 12M6 18 18 6',file:'M5 3h9l5 5v13H5Zm9 0v6h5M8 13h8m-8 4h6',refresh:'M20 8a8 8 0 1 0 0 8m0-13v5h-5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l3 2'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const button=(label,action,attrs='',primary=false)=>`<button class="btn ${primary?'primary':'secondary'}" data-action="${action}" ${attrs}>${label}${primary?icon('arrow',17):''}</button>`;
const courses=()=>[...DATA.courses,...state.courses],courseName=id=>courses().find(c=>c.id===id)?.name||'Personal course';
const httpsLink=value=>{try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:'';}catch{return '';}};
const weekLabel=days=>{const weeks=Math.floor(days/7),rest=days%7;return weeks+' '+(weeks===1?'week':'weeks')+' '+rest+' '+(rest===1?'day':'days');};
const dateLabel=(value,withTime=false)=>{if(!value)return 'Date not supplied';const d=new Date(value.length===7?value+'-01T12:00:00+07:00':value.length===10?value+'T12:00:00+07:00':value);return Number.isFinite(+d)?new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',...(withTime?{timeStyle:'short'}:{}),timeZone:ZONE}).format(d):'Date not supplied';};
function toast(message,undo=false){$('#toast').innerHTML=`<span>${e(message)}</span>${undo?'<button data-action="undo-exam">Undo</button>':''}`;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),undo?30000:5000);}
function commit(next,recovery=false){if(storageError&&!recovery)throw Error('Existing browser data needs recovery. Export it from the profile menu before restoring a backup.');state=saveState(next);storageError='';}
function openModal(title,body){if(!modal.open)lastFocus=document.activeElement;modalToken++;if(activePdf){activePdf.destroy();activePdf=null;}modal.innerHTML=`<header class="dialog-head"><h2 id="dialog-title">${e(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog" title="Close dialog">${icon('close')}</button></header><div class="dialog-body">${body}</div>`;if(!modal.open)modal.showModal();(modal.querySelector('.dialog-body input:not([disabled]),.dialog-body select,.dialog-body button')||modal.querySelector('[data-action="close-modal"]'))?.focus();return modalToken;}
let lastModalDismissal=-Infinity;
function closeModal(){lastModalDismissal=performance.now();modal.close();}
modal.addEventListener('close',()=>{if(modal.open)return;modalToken++;activePdf?.destroy();activePdf=null;const active=document.activeElement;if(lastFocus?.isConnected&&(!active||active===document.body||active===modal||modal.contains(active)))lastFocus.focus({preventScroll:true});});
function go(next){const normalized=['bookshelf','courses'].includes(next)?next:'home';if(location.hash!=='#'+normalized)location.hash=normalized;else navigate();}
function navigate(){if(!DATA)return;route=['bookshelf','courses'].includes(location.hash.slice(1))?location.hash.slice(1):'home';if(location.hash!=='#'+route)history.replaceState(null,'','#'+route);if(modal.open)closeModal();render();scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
function render(){if(!DATA)return;const focused=document.activeElement?.id,pos=document.activeElement?.selectionStart;document.documentElement.dataset.collapsed=String(state.collapsed);app.innerHTML=`<aside class="sidebar" aria-label="Main navigation"><a class="brand" href="#home"><span class="logo">Z.</span><span>Study<br>Studio</span></a><button class="collapse" data-action="collapse" aria-label="${state.collapsed?'Expand':'Collapse'} menu" title="${state.collapsed?'Expand':'Collapse'} menu">${icon('menu')}<span>${state.collapsed?'Expand':'Collapse'}</span></button><nav>${[['home','Home','home'],['bookshelf','Bookshelf','book'],['courses','Courses','book']].map(([id,label,art])=>`<a href="#${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''} aria-label="${label}" title="${label}">${icon(art)}<span>${label}</span></a>`).join('')}</nav><div class="sidebar-bottom"><button class="profile" data-action="data" aria-label="Local data and backups" title="Local data and backups"><span class="profile-mark" aria-hidden="true">Z</span><span><strong>Zin</strong><small>Local data & backups</small></span></button></div></aside><div class="workspace"><header class="topbar"><span class="breadcrumb">My workspace <span>/</span> <strong>${route==='home'?'The Daily':route==='courses'?'Courses':'Bookshelf'}</strong></span><form id="global-search" class="search" role="search">${icon('search')}<input id="global-query" name="query" type="search" aria-label="Search courses and books" placeholder="Find a course or book…"><kbd>/</kbd></form><button class="icon-btn" data-action="theme" aria-label="Switch light or dark theme" title="Switch light or dark theme">${icon('sun')}</button><button class="avatar-button" data-action="data" aria-label="Local data and backups" title="Local data and backups"><span aria-hidden="true">Z</span></button></header><main id="main" tabindex="-1">${storageError?`<div class="error" role="alert">${e(storageError)} ${button('Recover data','data')}</div>`:''}${route==='home'?home():route==='courses'?onlineCoursesView():bookshelf()}</main><footer>Saved on this browser <button data-action="data">Backups</button></footer></div>`;if(focused&&$( '#'+focused)){const el=$('#'+focused);el.focus({preventScroll:true});if(typeof pos==='number'&&el.setSelectionRange)try{el.setSelectionRange(pos,pos);}catch{}}todaySignature=signature();}
function home(){return `<section class="hero"><div><h1>Stay curious, <em>Zin.</em></h1><p>Your daily stories, case studies, and what’s ahead.</p></div><span class="date-chip">${icon('calendar',16)}${new Intl.DateTimeFormat('en-GB',{dateStyle:'full',timeZone:ZONE}).format(new Date())}</span></section><div class="daily-grid"><section id="market-pulse" class="panel reading-panel">${newsPanel()}</section><section id="case-panel" class="panel reading-panel">${casePanel()}</section></div><section id="exam-countdown" class="exam-section">${examsPanel()}</section>${homeCollections()}`;}
function stories(){return edition.items.map(englishStory).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,20);}
function media(item,isCase=false){const m=MEDIA_SNAPSHOTS[item.url]||item.image||NEWS_MEDIA[item.id];if(!m)return '';const src=m.method?m.src:isCase?'/api/reading/case-image?id='+encodeURIComponent(item.id):'/api/reading/image?id='+encodeURIComponent(item.id);return `<figure class="reading-media"><img src="${e(src)}" alt="${e(containsVietnamese(m.alt)?item.title:m.alt||item.title)}" referrerpolicy="no-referrer" loading="lazy"><figcaption><a href="${e(httpsLink(m.sourceUrl)||item.url)}" target="_blank" rel="noopener noreferrer">${e(containsVietnamese(m.credit)?'Source image · '+item.publisher:m.credit||item.publisher)}</a></figcaption></figure>`;}
function newsPanel(){const items=stories();newsIndex=((newsIndex%Math.max(1,items.length))+items.length)%Math.max(1,items.length);const story=items[newsIndex],failed=edition.sources?.filter(s=>s.error)||[];return `<header class="panel-title"><h2>Market Pulse</h2>${button(busy?'Refreshing…':'Refresh','refresh','aria-label="Refresh news" '+(busy?'disabled':''))}</header>${story?`<div class="reading-tile news-tile">${media(story)}<p class="tile-badge">${e(story.publisher)} · <time datetime="${e(story.date)}">${e(dateLabel(story.date))}</time></p><button class="tile-open reading-copy" data-action="story" data-id="${e(story.id)}" aria-label="Read story: ${e(story.title)}"><h3>${e(story.title)}</h3><span class="story-excerpt">${e(story.subtitle)}</span><span class="story-cta">Read story ${icon('arrow',15)}</span></button><div class="pager overlay-pager">${carouselButton('Previous story','news-prev',items.length<2,true)}<span class="sr-only" role="status">Story ${newsIndex+1} / ${items.length}</span>${carouselButton('Next story','news-next',items.length<2)}</div></div>`:`<div class="reading-tile empty-tile"><div class="empty"><h3>${busy?'Loading stories…':'No stories available yet'}</h3><p>Refresh to retry. Books and exams remain available.</p></div></div>`}<details class="reading-status"><summary>${edition.updatedAt?'Updated '+e(dateLabel(edition.updatedAt,true)):'Waiting for the first update'}${readingError?' · Using the latest available edition':failed.length?' · '+failed.length+' sources unavailable':''}</summary><div role="status"><p>Last successful update: ${e(dateLabel(edition.updatedAt,true))}</p>${readingError?`<p class="error-copy">${e(readingError)}</p>`:''}${failed.length?`<p>Unavailable sources: ${failed.map(s=>e(s.publisher)).join(', ')}. Latest available stories are kept.</p>`:''}</div></details>`;}

function carouselButton(label,action,disabled=false,back=false){return `<button class="carousel-arrow ${back?'back':''}" data-action="${action}" aria-label="${e(label)}" title="${e(label)}" ${disabled?'disabled':''}>${icon('arrow',19)}</button>`;}
function sourceDocumentLabel(item){return `<span>Source excerpt · ${e(item.sourceLabel)}</span>`;}
function localCases(){return localCaseSections(state.documents).map(c=>({...c,added:state.documents.find(d=>d.id===c.documentId)?.added}));}
function casePanel(){const local=localCases(),list=caseMode==='web'?edition.caseStudies:local,item=caseMode==='web'?dailyCase(list,caseOffset):list[((localIndex%Math.max(1,list.length))+list.length)%Math.max(1,list.length)];return `<header class="panel-title case-title"><h2>Today's case study</h2><div class="tabs" role="group" aria-label="Case source">${[['web','From the web'],['documents','Your documents']].map(([id,label])=>`<button data-action="case-tab" data-id="${id}" aria-pressed="${caseMode===id}">${label}</button>`).join('')}</div></header>${item?`<div class="reading-tile case-tile ${caseMode==='documents'?'local-tile':''}">${caseMode==='web'?media(item,true):`<div class="document-visual" aria-hidden="true">${icon('file',60)}</div>`}<p class="tile-badge">${e(caseMode==='web'?item.publisher+(item.campaignPeriod?' · historical case':''):item.sourceLabel)}</p><button class="tile-open reading-copy" data-action="case-open" data-id="${e(item.id)}" aria-label="Read case study: ${e(item.title)}"><h3>${e(item.title)}</h3><span class="tile-read">Read case study ${icon('arrow',15)}</span></button><div class="pager overlay-pager">${carouselButton('Previous case','case-prev',list.length<2,true)}<span class="sr-only">${list.length} cases in the library</span>${carouselButton('Next case','case-next',list.length<2)}</div></div><div class="case-summary-block"><p class="case-summary">${e(caseMode==='web'?item.summary:item.text.slice(0,240))}</p><div class="case-meta"><span>${caseMode==='web'?(item.date?'Published '+e(dateLabel(item.date)):'Publication date unavailable'):'Attached '+e(dateLabel(item.added))}</span>${caseMode==='web'?`<a href="${e(item.url)}" target="_blank" rel="noopener noreferrer">Source: ${e(item.publisher)}</a>`:sourceDocumentLabel(item)}</div>${button('Read case study','case-open',`data-id="${e(item.id)}"`,true)}</div>`:`<div class="reading-tile empty-tile"><div class="empty"><h3>${caseMode==='web'?'Case studies are unavailable':'Read from your own documents'}</h3><p>${caseMode==='web'?'Refresh Market Pulse to retry.':'Attach a PDF, DOCX or PPTX to read its excerpts.'}</p>${caseMode==='documents'?button('Add document','upload'):''}</div></div>` }`;}
function readingPanels(){if($('#market-pulse'))$('#market-pulse').innerHTML=newsPanel();if($('#case-panel'))$('#case-panel').innerHTML=casePanel();}
async function refresh(){if(busy)return;busy=true;readingPanels();try{edition=await fetchEdition();readingError='';}catch{readingError='Could not update. The latest available edition is kept; Refresh to retry.';}finally{busy=false;readingPanels();}}
function storyDialog(id){const item=stories().find(n=>n.id===id);if(!item)return;openModal(item.title,`${media(item)}<p class="source-label">${e(item.publisher)} · ${e(dateLabel(item.date))}</p><p>${e(item.subtitle)}</p><a class="btn primary" href="${e(item.url)}" target="_blank" rel="noopener noreferrer">Read the original source ${icon('arrow',17)}</a>`);}
function caseDialog(id){const local=localCases().find(c=>c.id===id),item=local||edition.caseStudies.find(c=>c.id===id);if(!item)return;openModal(item.title,`<p class="source-label">${e(local?item.sourceLabel:item.publisher+' · '+dateLabel(item.date))}</p>${local?'':`<a class="text-link" href="${e(item.url)}" target="_blank" rel="noopener noreferrer">Read the full case at its source ${icon('arrow',17)}</a>`}${!local?`<p class="source-label">${item.campaignPeriod?'Campaign: '+e(item.campaignPeriod)+' · ':''}Library checked: ${e(dateLabel(edition.caseUpdatedAt,true))}</p>`:''}<p class="source-body">${e(local?item.text.slice(0,12000):item.summary)}</p><p>${e(item.question||'What does the source establish, and what remains uncertain?')}</p><label for="case-reflection">Your reflection</label><textarea id="case-reflection" maxlength="20000">${e(state.notes['case:'+id]||'')}</textarea>${button('Save reflection','case-note',`data-id="${e(id)}"`)}${local?button('Open source document','local-document',`data-id="${e(item.documentId)}"`):''}`);}
function examCard(exam,lead=false){const status=examState(exam);return `<article class="exam-card ${lead?'next-exam':''} urgency-${status.urgency}" data-exam-id="${e(exam.id)}"><div class="exam-copy"><span class="status-label">${status.passed?'Completed':lead?'Next exam':status.urgencyLabel}</span><h3>${e(exam.subject)}</h3><p>${e(exam.type)} · ${e(dateLabel(exam.date))}${exam.time?' · '+e(exam.time):''}${exam.location?' · '+e(exam.location):''}</p>${exam.note?`<details class="exam-note-detail"><summary>Note</summary><p>${e(exam.note)}</p></details>`:''}<div class="exam-actions">${button('Edit','edit-exam',`data-id="${e(exam.id)}" aria-label="Edit ${e(exam.subject)} exam"`)}${button('Delete','delete-exam',`data-id="${e(exam.id)}" aria-label="Delete ${e(exam.subject)} exam"`)}</div></div><div class="exam-time ${!status.passed&&status.days===0?'today-count':status.days>999?'long-count':''}" role="group" aria-label="${e(status.label+(status.passed?'':' · '+status.urgencyLabel))}" title="${e(status.passed?'Passed':weekLabel(status.days))}"><strong>${status.passed?'Passed':status.days===0?'Today':status.days}</strong><span>${status.passed?'':status.days===0?'Good luck':status.days===1?'day left':'days left'}</span>${!status.passed&&status.days===0?`<time data-tick="${e(exam.id)}" aria-label="Time remaining">${tickLabel(exam)}</time>`:''}</div><div class="exam-progress" role="progressbar" aria-label="Calendar time elapsed since this exam was added" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${status.progress}"><span style="width:${status.progress}%"></span></div></article>`;}
function examsPanel(){const {upcoming,completed}=orderedExams(state.exams),[next,...other]=upcoming,undo=state.undo&&state.undo.until>Date.now(),unscheduled=DATA.courses.filter(c=>c.current&&!upcoming.some(exam=>exam.courseId===c.id||exam.subject.toLowerCase()===c.name.toLowerCase()));return `<div class="exam-dashboard"><div class="exam-main"><header class="section-title"><h2>Exam Countdown</h2>${button('Add exam','add-exam','',true)}</header>${next?examCard(next,true):`<div class="exam-empty"><span class="empty-icon">${icon('calendar',28)}</span><div><h3>No exams scheduled</h3><p>Add a date when you're ready.</p></div></div>`}</div><aside class="other-exams" aria-label="Other subjects"><h3>Other subjects</h3><div class="exam-list">${other.map(exam=>{const status=examState(exam);return `<article class="exam-card compact-exam urgency-${status.urgency}" data-exam-id="${e(exam.id)}"><button class="other-main" data-action="edit-exam" data-id="${e(exam.id)}" aria-label="Edit ${e(exam.subject)} exam"><strong>${e(exam.subject)}</strong><span>${e(dateLabel(exam.date))} · ${status.label}</span></button><button class="remove-exam" data-action="delete-exam" data-id="${e(exam.id)}" aria-label="Delete ${e(exam.subject)} exam" title="Delete ${e(exam.subject)} exam">${icon('close',13)}</button></article>`;}).join('')}</div>${unscheduled.length?`<div class="quick-picks" role="group" aria-label="Choose a current course">${unscheduled.map(c=>`<button data-action="add-exam" data-course="${e(c.id)}" title="Add an exam for ${e(c.name)}"><strong>${e(c.name)}</strong><span>No upcoming exam ${icon('plus',12)}</span></button>`).join('')}</div>`:''}${!other.length&&!unscheduled.length?'<p class="no-other-exams">No other upcoming exams.</p>':''}</aside></div>${undo?`<div class="undo-banner" role="status">Exam deleted. ${button('Undo','undo-exam')}</div>`:''}${completed.length?`<details class="completed-exams"><summary>Completed (${completed.length})</summary><div class="exam-grid">${completed.map(exam=>examCard(exam)).join('')}</div></details>`:''}`;}
function courseExam(course){return orderedExams(state.exams).upcoming.find(exam=>exam.courseId===course.id||exam.subject.toLowerCase()===course.name.toLowerCase());}
function bookCards(list){return list.map(c=>{const book=c.books?.[0],exam=courseExam(c),link=c.id==='consumer-behaviour'?DATA.links.consumerBehaviorLab:null;return `<article class="book-card panel"><${link?'a':'button'} class="book-main" ${link?`href="${e(link)}" target="_blank" rel="noopener noreferrer"`:`data-action="course" data-id="${e(c.id)}"`} aria-label="Open ${e(c.name)}${link?' study website in a new tab':''}"><div class="book-cover">${c.cover?`<img src="${e(c.cover.src)}" alt="${e((c.cover.kind==='slides'?'Title slide: ':'Cover: ')+(book?.title||c.name))}" width="${c.cover.width}" height="${c.cover.height}" loading="lazy">`:`<div class="plain-cover">${icon('book',44)}<strong>${e(c.name)}</strong></div>`}</div><span class="course-tag">${e(c.name)}</span><h2>${e(book?.title||c.name)}</h2><p>${e(book?.authors?.join(', ')||'Your documents')}</p>${c.current?'<span class="semester-tag">Current semester</span>':c.cover?.kind==='slides'?'<span class="semester-tag">Course slides</span>':''}${exam?`<span class="exam-chip urgency-${examState(exam).urgency}">Exam in ${examState(exam).days} days</span>`:''}</${link?'a':'button'}>${state.documents.some(d=>d.courseId===c.id)?button('Your documents','course',`data-id="${e(c.id)}"`):''}</article>`;}).join('');}
function bookshelf(){const list=courses().filter(c=>(filter==='all'||c.current)&&`${c.name} ${(c.books||[]).map(b=>b.title+' '+b.authors.join(' ')).join(' ')}`.toLowerCase().includes(query.toLowerCase()));return `<section class="hero bookshelf-hero"><div><h1>Good books. <em>Bigger ideas.</em></h1><p>Your course books, all in one place.</p></div>${button('Add document','upload','',true)}</section><div class="shelf-toolbar"><label class="search"><span class="sr-only">Search bookshelf</span>${icon('search')}<input id="shelf-search" type="search" value="${e(query)}" placeholder="Search courses, books or authors"></label><select id="shelf-filter" aria-label="Filter courses"><option value="all" ${filter==='all'?'selected':''}>All courses</option><option value="current" ${filter==='current'?'selected':''}>Current semester</option></select>${button('New course','new-course')}</div><div class="bookshelf-grid">${bookCards(list)}</div>${!list.length?'<div class="panel empty"><h2>No books found</h2><p>Try another title or select All courses.</p></div>':''}`;}

async function loadOnlineCourses(){try{const response=await fetch('data/online-courses.json',{cache:'no-cache'});if(!response.ok)throw Error('Course sources are unavailable. Retry to reload the catalog.');ONLINE=validateCourses(await response.json());coursesError='';}catch(error){coursesError=error.message;}}
function onlineControls(){return `<div class="online-course-controls"><label class="search">${icon('search',17)}<span class="sr-only">Search marketing courses</span><input id="courses-search" type="search" value="${e(onlineQuery)}" placeholder="Search marketing courses…"></label><select id="courses-provider" aria-label="Filter course provider"><option value="all">All providers</option>${[...new Set(ONLINE.courses.map(c=>c.provider))].map(p=>`<option ${p===providerFilter?'selected':''}>${e(p)}</option>`).join('')}</select><select id="courses-delivery" aria-label="Filter course delivery"><option value="all">All formats</option><option value="online" ${deliveryFilter==='online'?'selected':''}>Online only</option></select></div>`;}
function onlineCoursesView(){const list=filterCourses(ONLINE.courses,onlineQuery,providerFilter,deliveryFilter);return `<section class="hero courses-hero"><div><h1>Courses. <em>Level up your marketing skills.</em></h1><p>Explore marketing courses from official global and Vietnam-based providers.</p></div></section>${onlineControls()}${coursesError?`<div class="error" role="alert">${e(coursesError)} ${button('Retry','reload-courses')}</div>`:''}<div class="online-courses-grid">${courseCards(list)}</div>${!list.length&&!coursesError?'<div class="panel empty"><h2>No matching courses</h2><p>Try another provider or clear your search.</p><button class="btn secondary" data-action="clear-course-filters">Clear filters</button></div>':''}<p class="provider-note">Sources checked ${e(dateLabel(ONLINE.checkedOn))}. Current pricing, access and delivery are confirmed by each provider. Visiting a course does not enroll you or change learning progress.</p>`;}
function homeCollections(){return `<section class="home-collection"><header class="collection-head"><div><span class="collection-breadcrumb">My workspace / Bookshelf</span><h2>Good books. <em>Bigger ideas.</em></h2><p>Your current course books, all in one place.</p></div><a class="btn primary" href="#bookshelf">View bookshelf ${icon('arrow',16)}</a></header><div class="bookshelf-grid home-books">${bookCards(DATA.courses.filter(c=>c.current).slice(0,4))}</div></section><section class="home-collection"><header class="collection-head"><div><span class="collection-breadcrumb">My workspace / Courses</span><h2>Courses. <em>Level up your marketing skills.</em></h2><p>Curated options from official providers.</p></div><a class="btn primary" href="#courses">View all courses ${icon('arrow',16)}</a></header>${coursesError?`<p class="error-copy">${e(coursesError)} ${button('Retry','reload-courses')}</p>`:''}<div class="online-courses-grid">${courseCards(ONLINE.courses.slice(0,5))}</div></section>`;}

function courseDialog(id){const c=courses().find(c=>c.id===id);if(!c)return;openModal(c.name,`${(c.books||[]).map(b=>{const material=catalog.find(m=>m.id===b.id)||catalog.find(m=>m.courseId===c.id);return `<article class="document-row"><div><h3>${e(b.title)}</h3><p>${e(b.authors.join(', '))}</p></div>${material?`<a class="btn secondary" href="/api/materials/${encodeURIComponent(material.id)}" target="_blank" rel="noopener noreferrer">Open original ${icon('arrow',17)}</a>`:'<span class="source-label">Attach the original document to read it here.</span>'}</article>`;}).join('')}${state.documents.filter(d=>d.courseId===id).map(d=>`<article class="document-row"><div><h3>${e(d.name)}</h3><p>${d.type.toUpperCase()} · ${d.pages||0} pages/sections</p></div>${button('Open','local-document',`data-id="${e(d.id)}"`)}</article>`).join('')}${button('Add document','upload',`data-course="${e(id)}"`,true)}`);}
function examDialog(id,courseId=''){const old=state.exams.find(exam=>exam.id===id),known=old?courses().find(c=>c.id===old.courseId):courses().find(c=>c.id===courseId),custom=old&&!known;openModal(old?'Edit exam':'Add exam',`<form id="exam-form" data-id="${e(old?.id||'')}"><label for="exam-subject">Subject</label><select id="exam-subject" name="subject">${courses().map(c=>`<option value="${e(c.id)}" ${known?.id===c.id?'selected':''}>${e(c.name)}</option>`).join('')}<option value="custom" ${custom?'selected':''}>Custom subject</option></select><div id="custom-subject-field" ${custom?'':'hidden'}><label for="exam-custom">Custom subject</label><input id="exam-custom" name="custom" maxlength="150" value="${e(custom?old.subject:'')}" ${custom?'required':'disabled'}></div><div class="form-grid"><label>Exam type<select name="type">${['Midterm','Final','Quiz','Other'].map(type=>`<option ${old?.type===type?'selected':''}>${type}</option>`).join('')}</select></label><label>Date<input name="date" type="date" min="1900-01-01" max="2200-12-31" value="${e(old?.date||'')}" required></label><label>Time (optional)<input name="time" type="time" value="${e(old?.time||'')}"></label><label>Room / location (optional)<input name="location" maxlength="200" value="${e(old?.location||'')}"></label></div><label for="exam-note">Note (optional)</label><textarea id="exam-note" name="note" maxlength="2000">${e(old?.note||'')}</textarea><p class="source-label">Vietnam time. Without a time, the countdown ends at the end of the exam date.</p><p id="exam-error" class="error-copy" role="alert"></p><div class="actions">${button('Cancel','close-modal')}<button class="btn primary" type="submit">Save exam ${icon('arrow',17)}</button></div></form>`);}
function uploadDialog(courseId=''){openModal('Add document',`<p>PDF up to 100 MB; DOCX/PPTX up to 30 MB. Files stay on this device and are not sent to an AI service.</p><form id="upload-form"><label for="upload-course">Course</label><select id="upload-course" name="course">${courses().map(c=>`<option value="${e(c.id)}" ${courseId===c.id?'selected':''}>${e(c.name)}</option>`).join('')}</select><label for="document-file">Document</label><input id="document-file" name="document" type="file" accept=".pdf,.docx,.pptx" required><p class="source-label">Text extraction only. Scanned pages need OCR elsewhere; legacy .ppt is unsupported.</p><p id="upload-status" role="status"></p><button class="btn primary" type="submit">Attach document ${icon('arrow',17)}</button></form>`);}
async function upload(form){const submit=form.querySelector('[type="submit"]'),status=$('#upload-status'),token=modalToken;submit.disabled=true;try{status.textContent='Checking document…';const file=form.elements.document.files[0],checked=await inspectFile(file),courseId=form.elements.course.value,existing=state.documents.find(d=>(d.hash||d.id)===checked.id&&d.courseId===courseId);let doc=existing;if(!doc){let pages,sections=[];if(checked.type==='pdf'){const pdf=await loadPdf(checked.bytes);pages=pdf.numPages;await pdf.destroy();}else{sections=await officeSections(checked.bytes,checked.type);pages=sections.length;}const id=state.documents.some(d=>d.id===checked.id)?checked.id+'-'+courseId:checked.id;doc={id,hash:checked.id,name:file.name,courseId,type:checked.type,pages,sections,added:new Date().toISOString(),bytes:file.size};await putFile(id,file);const next=structuredClone(state);next.documents.push(doc);commit(next);}else await putFile(doc.id,file);if(token!==modalToken)return;closeModal();render();await localDocument(doc.id);}catch(error){if(token===modalToken)status.textContent=error.message;}finally{submit.disabled=false;}}
async function localDocument(id){const doc=state.documents.find(d=>d.id===id);if(!doc)return;const token=openModal(doc.name,`<p>Loading the original document…</p>`);try{const file=await getFile(id);if(!file)throw Error('The original file is missing on this device. Add the same document again to reattach it.');if(token!==modalToken)return;const url=URL.createObjectURL(file);modal.addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});modal.querySelector('.dialog-body').innerHTML=`<p class="source-label">${e(courseName(doc.courseId))} · ${doc.type.toUpperCase()} · ${doc.pages} pages/sections</p><a class="btn secondary" href="${url}" target="_blank" rel="noopener noreferrer">Open original document ${icon('arrow',17)}</a>${doc.type==='pdf'?`<form id="extract-form" data-id="${e(id)}"><p>Choose up to 30 pages to extract for Your documents.</p><div class="form-grid"><label>First page<input name="start" type="number" min="1" max="${doc.pages}" value="1" required></label><label>Last page<input name="end" type="number" min="1" max="${doc.pages}" value="${Math.min(5,doc.pages)}" required></label></div><p id="extract-status" role="status"></p><button class="btn primary" type="submit">Extract selected text ${icon('arrow',17)}</button></form>`:''}<div id="document-sections">${sectionsView(doc)}</div>`;}catch(error){if(token===modalToken)modal.querySelector('.dialog-body').innerHTML=`<p class="error" role="alert">${e(error.message)}</p>${button('Reattach document','upload',`data-course="${e(doc.courseId)}"`)}`;}}
function sectionsView(doc){return `<h3 class="section-label">Extracted sections (${doc.sections.length})</h3>${doc.sections.map(s=>`<details class="source-section"><summary>${doc.type==='pptx'?'Slide':'Page/section'} ${s.page}${s.warning?' · Check source':''}</summary>${s.warning?`<p class="error-copy">${e(s.warning)}</p>`:''}<p class="source-body">${e(s.text||'No readable text was extracted.')}</p></details>`).join('')}`;}
async function extract(form){const token=modalToken,submit=form.querySelector('button'),status=$('#extract-status'),doc=state.documents.find(d=>d.id===form.dataset.id);submit.disabled=true;try{const file=await getFile(doc.id);activePdf=await loadPdf(new Uint8Array(await file.arrayBuffer()));const start=Number(form.elements.start.value),end=Number(form.elements.end.value),sections=await pdfSections(activePdf,start,end,(done,total)=>{if(token===modalToken)status.textContent=`Processing ${done} of ${total} pages…`;});if(token!==modalToken)return;const next=structuredClone(state),target=next.documents.find(d=>d.id===doc.id);target.sections=[...new Map([...target.sections,...sections].map(s=>[s.page,s])).values()].sort((a,b)=>a.page-b.page);commit(next);$('#document-sections').innerHTML=sectionsView(target);status.textContent=`Saved ${sections.length} sections. ${sections.filter(s=>s.warning).length} need a source check.`;readingPanels();}catch(error){if(token===modalToken)status.textContent=error.message;}finally{activePdf?.destroy();activePdf=null;submit.disabled=false;}}
function dataDialog(){openModal('Local data & backups',`<p>Books, extracted sections, reflections and exams are saved on this browser. A JSON backup does not include original files; keep those separately.</p><div class="actions">${button('Export backup','backup')}${button('Import backup','import')}</div>${storageError?`<p class="error">${e(storageError)}</p>${button('Export recovery data','recovery')}`:''}`);}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function signature(){return calendarDate()+'|'+orderedExams(state.exams).upcoming.map(e=>e.id).join('|')+'|'+Boolean(state.undo&&state.undo.until>Date.now());}
document.addEventListener('click',async event=>{if(event.detail>1&&performance.now()-lastModalDismissal<400){event.preventDefault();event.stopImmediatePropagation();return;}const nav=event.target.closest('.sidebar a[href^="#"]');if(nav){event.preventDefault();go(nav.hash.slice(1));return;}if(event.target.closest('.skip')){event.preventDefault();$('#main')?.focus();return;}const b=event.target.closest('[data-action]');if(!b||b.disabled||!DATA)return;const {action,id,course}=b.dataset;try{switch(action){
 case 'reload-courses':await loadOnlineCourses();render();break;case 'clear-course-filters':onlineQuery='';providerFilter='all';deliveryFilter='all';render();break;case 'close-modal':closeModal();break;case 'data':dataDialog();break;
 case 'collapse':{const next=structuredClone(state);next.collapsed=!next.collapsed;commit(next);render();break;}
 case 'theme':{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('zin-theme',theme);}catch{toast('Theme changed for this visit.');}break;}
 case 'refresh':await refresh();break;case 'news-next':newsIndex++;readingPanels();break;case 'news-prev':newsIndex--;readingPanels();break;case 'story':storyDialog(id);break;
 case 'case-tab':caseMode=id;readingPanels();break;case 'case-next':caseMode==='web'?caseOffset++:localIndex++;readingPanels();break;case 'case-prev':caseMode==='web'?caseOffset--:localIndex--;readingPanels();break;case 'case-open':caseDialog(id);break;
 case 'case-note':{const next=structuredClone(state);next.notes['case:'+id]=$('#case-reflection').value;commit(next);toast('Reflection saved.');break;}
 case 'course':courseDialog(id);break;case 'upload':uploadDialog(course);break;case 'local-document':await localDocument(id);break;
 case 'new-course':openModal('New course',`<form id="course-form"><label for="course-name">Course name</label><input id="course-name" name="name" maxlength="200" required><label class="check-label"><input type="checkbox" name="current"> Current semester</label><p id="course-error" class="error-copy" role="alert"></p><button class="btn primary" type="submit">Create course ${icon('arrow',17)}</button></form>`);break;
 case 'add-exam':examDialog(null,course);break;case 'edit-exam':examDialog(id);break;
 case 'delete-exam':{const exam=state.exams.find(e=>e.id===id);if(exam)openModal('Delete exam?',`<p>Delete ${e(exam.subject)} · ${e(exam.type)} · ${e(dateLabel(exam.date))}?</p><div class="actions">${button('Cancel','close-modal')}${button('Delete exam','confirm-delete',`data-id="${e(id)}"`)}</div>`);break;}
 case 'confirm-delete':{const exam=state.exams.find(e=>e.id===id);if(!exam)return;const next=structuredClone(state);next.exams=next.exams.filter(e=>e.id!==id);next.undo={exam,until:Date.now()+30000};commit(next);closeModal();render();toast('Exam deleted.',true);break;}
 case 'undo-exam':{if(!state.undo||state.undo.until<Date.now())return;const next=structuredClone(state);if(!next.exams.some(e=>e.id===next.undo.exam.id))next.exams.push(next.undo.exam);next.undo=null;commit(next);render();toast('Exam restored.');break;}
 case 'backup':download('zin-studio-backup-'+calendarDate()+'.json',{kind:'zin-studio-backup',version:2,state});break;
 case 'recovery':{let original;try{original={current:localStorage.getItem(STORAGE_KEY),previous:localStorage.getItem('zin-studio-v1')};}catch{original={error:'Browser storage could not be read.'};}download('zin-studio-recovery.json',original);break;}
 case 'import':openModal('Import backup',`<p>Current notes take priority. Original files must be reattached on a new device.</p><form id="backup-form"><label for="backup-file">Studio JSON backup</label><input id="backup-file" name="file" type="file" accept=".json" required><p id="backup-error" class="error-copy" role="alert"></p><button class="btn primary" type="submit">Validate and merge ${icon('arrow',17)}</button></form>`);break;
 }}catch(error){toast(error.message||'Could not finish. Your input is kept.');}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;if(form.dataset.submitting==='true')return;try{
 if(form.id==='global-search'){const value=form.elements.query.value.trim();const booksMatch=courses().some(c=>(c.name+' '+(c.books||[]).map(b=>b.title+' '+b.authors.join(' ')).join(' ')).toLowerCase().includes(value.toLowerCase()));if((route==='courses'&&(!booksMatch||filterCourses(ONLINE.courses,value).length))||(!booksMatch&&filterCourses(ONLINE.courses,value).length)){onlineQuery=value;providerFilter='all';deliveryFilter='all';go('courses');}else{query=value;filter='all';go('bookshelf');}return;}
 if(form.id==='upload-form'){await upload(form);return;}if(form.id==='extract-form'){await extract(form);return;}
 if(form.id==='exam-form'){const old=state.exams.find(e=>e.id===form.dataset.id),course=courses().find(c=>c.id===form.elements.subject.value),exam=validateExam({id:old?.id||uid(),subject:course?.name||form.elements.custom.value,courseId:course?.id||'',type:form.elements.type.value,date:form.elements.date.value,time:form.elements.time.value,location:form.elements.location.value,note:form.elements.note.value,addedAt:old?.addedAt||new Date().toISOString()});if(duplicateExam(state.exams,exam))throw Error('This subject, exam type, date and time already exist. Edit the existing exam instead.');const next=structuredClone(state);next.exams=[...next.exams.filter(e=>e.id!==exam.id),exam];commit(next);form.dataset.submitting='true';closeModal();render();toast('Exam saved.');return;}
 if(form.id==='course-form'){const name=form.elements.name.value.trim();if(!name)throw Error('Enter a course name.');if(courses().some(c=>c.name.toLowerCase()===name.toLowerCase()))throw Error('This course is already on your shelf.');const next=structuredClone(state);next.courses.push({id:'course-'+uid(),name,current:form.elements.current.checked,books:[]});commit(next);form.dataset.submitting='true';closeModal();go('bookshelf');return;}
 if(form.id==='backup-form'){const file=form.elements.file.files[0];if(!file||file.size>18000000)throw Error('Choose a Studio JSON backup under 18 MB.');const value=JSON.parse(await file.text());if(value.kind!=='zin-studio-backup'||![1,2].includes(value.version))throw Error('Choose a valid Studio backup.');const next=mergeState(state,validateState(value.state));commit(next,true);closeModal();render();toast('Backup merged.');}
 }catch(error){const target=form.querySelector('[role="alert"]');if(target)target.textContent=error.message;else toast(error.message);}});
document.addEventListener('input',event=>{if(event.target.id==='shelf-search'){query=event.target.value;render();}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='shelf-filter'){filter=el.value;render();}if(el.id==='exam-subject'){const custom=el.value==='custom';$('#custom-subject-field').hidden=!custom;$('#exam-custom').disabled=!custom;$('#exam-custom').required=custom;}});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!event.target.matches('input,textarea,select')&&!modal.open){event.preventDefault();$('#global-query')?.focus();}});
document.addEventListener('error',event=>{if(event.target instanceof HTMLImageElement){event.target.hidden=true;const figure=event.target.closest('figure');if(figure&&!figure.querySelector('.image-error'))figure.insertAdjacentHTML('afterbegin','<p class="image-error">Source image unavailable</p>');}},true);
addEventListener('hashchange',navigate);
setInterval(()=>{if(document.hidden||!DATA)return;const next=signature();if(next!==todaySignature){if(route==='home')$('#exam-countdown').innerHTML=examsPanel();else render();todaySignature=next;}document.querySelectorAll('[data-tick]').forEach(el=>{const exam=state.exams.find(e=>e.id===el.dataset.tick);if(exam)el.textContent=tickLabel(exam);});},1000);
setInterval(()=>{if(!document.hidden&&route==='home')refresh();},REFRESH_MS);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&route==='home'){refresh();if(DATA)render();}});
try{const response=await fetch('data/studio.json');if(!response.ok)throw Error('Could not load the bookshelf.');DATA=await response.json();await loadOnlineCourses();if(loaded.fresh)state.exams=(DATA.exams||[]).map(validateExam);catalog=await fetch('data/materials.json').then(r=>r.ok?r.json():[]).catch(()=>[]);navigate();refresh();}catch(error){app.innerHTML=`<main class="boot"><h1>The studio needs another moment.</h1><p>${e(error.message)}</p><button class="btn primary" onclick="location.reload()">Retry</button></main>`;}

document.addEventListener('input',event=>{if(event.target.id==='courses-search'){onlineQuery=event.target.value;render();}});
document.addEventListener('change',event=>{if(event.target.id==='courses-provider'){providerFilter=event.target.value;render();}if(event.target.id==='courses-delivery'){deliveryFilter=event.target.value;render();}});
